UPDATE jq_authentication_type
SET
authentication_properties=JSON_SET(authentication_properties,'$.authenticationDetail.configurations[0]',JSON_ARRAY_APPEND(JSON_ARRAY_APPEND(JSON_EXTRACT(authentication_properties,'$.authenticationDetail.configurations[0]'),'$',IF(JSON_SEARCH(authentication_properties,'one','testSamlAuth',NULL,'$.authenticationDetail.configurations[0][*].name')IS NULL,JSON_OBJECT('name','testSamlAuth','type','button','textValue','Test','required',true,'value','Test'),NULL)),'$',IF(JSON_SEARCH(authentication_properties,'one','removeSamlAuth',NULL,'$.authenticationDetail.configurations[0][*].name')IS NULL,JSON_OBJECT('name','removeSamlAuth','type','button','textValue','Remove','required',true,'value','Remove'),NULL))),default_auth_properties=JSON_SET(default_auth_properties,'$.authenticationDetail.configurations[0]',JSON_ARRAY_APPEND(JSON_ARRAY_APPEND(JSON_EXTRACT(default_auth_properties,'$.authenticationDetail.configurations[0]'),'$',IF(JSON_SEARCH(default_auth_properties,'one','testSamlAuth',NULL,'$.authenticationDetail.configurations[0][*].name')IS NULL,JSON_OBJECT('name','testSamlAuth','type','button','textValue','Test','required',true,'value','Test'),NULL)),'$',IF(JSON_SEARCH(default_auth_properties,'one','removeSamlAuth',NULL,'$.authenticationDetail.configurations[0][*].name')IS NULL,JSON_OBJECT('name','removeSamlAuth','type','button','textValue','Remove','required',true,'value','Remove'),NULL)))
WHERE authentication_id=5;